using UnityEngine;
namespace Blocklands {public partial class Sandbox
{
    Camera secretMonitorCamera;RenderTexture secretMonitorTexture;bool monitorOpen,monitorOffline;int monitorView;float monitorNextFrame;Vector2 cameraListScroll;OwnedHome monitorHome;public bool SecretMonitorOpen=>monitorOpen;public RenderTexture SecretMonitorTexture=>secretMonitorTexture;public int MonitorViewCount=>3+InstalledCameras.Count;public bool MonitorOffline=>monitorOffline;
    string MonitorTitle=>monitorView<3?(monitorView==0?"村庄鸟瞰":monitorView==1?"北岸看浪":"木板入口"):"我安装的摄像头"+InstalledCameras[monitorView-3].id;
    void EnsureSecretMonitorCamera(){if(secretMonitorCamera!=null&&secretMonitorTexture!=null)return;secretMonitorTexture=new RenderTexture(640,360,16){name="游戏内密室监控画面"};secretMonitorTexture.Create();var o=new GameObject("村庄监控摄像机（不录制电脑屏幕）");o.transform.SetParent(secretRoomRoot,false);secretMonitorCamera=o.AddComponent<Camera>();secretMonitorCamera.enabled=false;secretMonitorCamera.targetTexture=secretMonitorTexture;secretMonitorCamera.nearClipPlane=.2f;secretMonitorCamera.farClipPlane=240;secretMonitorCamera.fieldOfView=62;secretMonitorCamera.cullingMask=~(1<<2);secretMonitorCamera.backgroundColor=World.SkyColor;secretMonitorCamera.clearFlags=CameraClearFlags.SolidColor;secretMonitorCamera.allowHDR=false;}
    void BuildSecretMonitor(Transform room,OwnedHome home){EnsureSecretMonitorCamera();var root=new GameObject("密室实时监控屏").transform;root.SetParent(room,false);root.localPosition=new Vector3(5.5f,0,.35f);var a=root.gameObject.AddComponent<RoyalArt>();a.Piece("监控外框",new Vector3(0,2.2f,0),new Vector3(3.1f,1.85f,.2f),new Color(.12f,.17f,.21f),PrimitiveType.Cube,true);var screen=a.Piece("实时监控画面",new Vector3(0,2.2f,.115f),new Vector3(2.9f,1.62f,1),Color.white,PrimitiveType.Quad,false);screen.localRotation=Quaternion.Euler(0,180,0);var fixture=root.gameObject.AddComponent<SecretRoomFixture>();fixture.Kind=SecretFixtureKind.Monitor;fixture.Home=home;fixture.OwnedMaterial=new Material(Resources.Load<Shader>("CCTVScreen"));fixture.OwnedMaterial.mainTexture=secretMonitorTexture;screen.GetComponent<Renderer>().sharedMaterial=fixture.OwnedMaterial;PlaceSign(room,"H打开实时监控 · 看浪往哪里走",new Vector3(5.5f,3.55f,.55f));room.Find("H打开实时监控 · 看浪往哪里走").localRotation=Quaternion.Euler(0,180,0);}
    public bool OpenSecretMonitor(OwnedHome home=null){home=home??FindSecretHome();if(home==null||home.secretRoomVersion!=1){Notice="先修建或补齐10×10密室，里面才有监控屏。";return false;}if(CompanionReturnBlocked){Notice="先结束当前游玩项目，再看监控。";return false;}if(LifeWorkshopOpen)CloseLifeWorkshop();if(SecretRoomMenuOpen)CloseSecretMenu();monitorHome=home;monitorOpen=true;monitorView=0;EnsureSecretMonitorCamera();SetPaused(false);RenderSecretMonitor(true);Notice="监控不会暂停海啸。按H或Esc关闭；按钮可切换鸟瞰、北岸和入口。";return true;}
    public void CloseSecretMonitor(){monitorOpen=false;monitorHome=null;}
    void DisposeSecretMonitor(){CloseSecretMonitor();if(secretMonitorCamera!=null){secretMonitorCamera.targetTexture=null;Destroy(secretMonitorCamera.gameObject);}secretMonitorCamera=null;if(secretMonitorTexture!=null){secretMonitorTexture.Release();Destroy(secretMonitorTexture);}secretMonitorTexture=null;}
    public void SetSecretMonitorView(int view){monitorView=Mathf.Clamp(view,0,MonitorViewCount-1);RenderSecretMonitor(true);}
    public void RenderSecretMonitor(bool force=false){if(secretMonitorCamera==null||secretMonitorTexture==null||!force&&Time.unscaledTime<monitorNextFrame)return;monitorNextFrame=Time.unscaledTime+.12f;monitorView=Mathf.Clamp(monitorView,0,MonitorViewCount-1);monitorOffline=false;var h=monitorHome??FindSecretHome();Vector3 position,target;if(monitorView>=3){var installed=InstalledCameras[monitorView-3];if(installed.region!=World.Region){monitorOffline=true;var old=RenderTexture.active;RenderTexture.active=secretMonitorTexture;GL.Clear(true,true,new Color(.07f,.11f,.15f));RenderTexture.active=old;return;}position=installed.position+installed.forward*.38f+Vector3.up*.12f;target=position+installed.forward*15;}else if(monitorView==2&&h!=null){position=new Vector3(h.x+5.2f,h.y+5.4f,h.z+3);target=new Vector3(h.x+3,h.y+1.94f,h.z+3);}else if(monitorView==1){position=new Vector3(48,110,-14);target=new Vector3(48,38,50);}else{position=new Vector3(48,126,47);target=new Vector3(48,14,48);}secretMonitorCamera.transform.SetPositionAndRotation(position,Quaternion.LookRotation(target-position));secretMonitorCamera.Render();}
    void DrawSecretMonitor(float w,float h){float x=w/2-450,y=h/2-285;Panel(new Rect(x,y,900,570),new Color(.08f,.13f,.18f,.98f));Label(new Rect(x+22,y+13,680,37),"密室监控 · "+MonitorTitle,24,Color.white);if(GUI.Button(new Rect(x+755,y+12,123,36),"关闭 · H/Esc")){CloseSecretMonitor();return;}if(secretMonitorTexture!=null)GUI.DrawTexture(new Rect(x+20,y+64,650,366),secretMonitorTexture,ScaleMode.ScaleToFit);if(monitorOffline)Label(new Rect(x+40,y+174,610,105),"这个镜头安装在“"+VoxelWorld.RegionNames[InstalledCameras[monitorView-3].region]+"”。\n该地图尚未加载，镜头离线；不会显示别的地区冒充现场。",20,Color.white,TextAnchor.MiddleCenter);DrawFloodMap(new Rect(x+687,y+64,190,190));Label(new Rect(x+689,y+265,185,105),"浪：北 → 南\n水面高度："+TsunamiWaterLevel.ToString("0.0")+"米\n倒地等待："+FloodDownCount+"人\n已救起："+FloodRescuedCount+"人",16,new Color(.7f,.93f,1));cameraListScroll=GUI.BeginScrollView(new Rect(x+687,y+379,191,110),cameraListScroll,new Rect(0,0,168,Mathf.Max(32,InstalledCameras.Count*32)));for(int i=0;i<InstalledCameras.Count;i++){var c=InstalledCameras[i];if(GUI.Button(new Rect(0,i*32,165,29),"镜头"+c.id+(c.region==World.Region?" · 实时":" · 离线")))SetSecretMonitorView(3+i);}GUI.EndScrollView();for(int i=0;i<3;i++)if(GUI.Button(new Rect(x+20+i*219,y+448,210,38),i==0?"1 村庄鸟瞰":i==1?"2 北岸看浪":"3 木板入口"))SetSecretMonitorView(i);if(GUI.Button(new Rect(x+687,y+515,191,35),"打开无人机")){OpenDroneFromMonitor();return;}Label(new Rect(x+22,y+501,650,47),TsunamiActive?"实时画面 · "+TsunamiCaption+"\n海啸仍在运行；密室木板门关好才有保护。":"右侧列表是你安装的镜头；←→也可切换。\n这里只显示游戏内场景，不录制电脑屏幕。",16,new Color(.8f,.9f,.92f));}
    void DrawFloodMap(Rect box){Panel(box,new Color(.15f,.28f,.3f));Label(new Rect(box.x,box.y-23,box.width,21),"村庄与浪头位置",14,Color.white,TextAnchor.MiddleCenter);for(int k=0;k<TsunamiFrontCount;k++){float z=TsunamiFront(k);if(z>=0&&z<=96)Panel(new Rect(box.x,box.y+z/96*box.height,box.width,3),new Color(.4f,.86f,1));}foreach(var plot in VoxelWorld.VillagePlots)Panel(new Rect(box.x+plot.x/96f*box.width,box.y+plot.y/96f*box.height,10/96f*box.width,10/96f*box.height),new Color(.89f,.69f,.42f));foreach(var victim in floodResidents)if(victim!=null&&victim.Downed){var p=victim.transform.position;Panel(new Rect(box.x+p.x/96*box.width-2,box.y+p.z/96*box.height-2,4,4),new Color(.99f,.45f,.55f));}}
